func (r *reader) decodeFailure() (*Failure, error) {
	if r.at() != '{' {
		return nil, r.refuse("wrong_type")
	}
	if err := r.enter(); err != nil {
		return nil, err
	}
	r.pos++
	v := &Failure{}
	var seen uint32
	r.ws()
	if r.at() != '}' {
		for {
			r.ws()
			if r.at() != '"' {
				return nil, r.refuse("malformed")
			}
			key, err := r.str()
			if err != nil {
				return nil, err
			}
			r.ws()
			if r.at() != ':' {
				return nil, r.refuse("malformed")
			}
			r.pos++
			r.ws()
			switch key {
			case "error":
				if seen&1 != 0 {
					return nil, r.refuse("duplicate_field")
				}
				seen |= 1
				x, err := r.str()
				if err != nil {
					return nil, err
				}
				v.Error = x
			case "permanent":
				if seen&2 != 0 {
					return nil, r.refuse("duplicate_field")
				}
				seen |= 2
				x, err := r.boolean()
				if err != nil {
					return nil, err
				}
				v.Permanent = x
			case "cause":
				if seen&4 != 0 {
					return nil, r.refuse("duplicate_field")
				}
				seen |= 4
				x, err := r.str()
				if err != nil {
					return nil, err
				}
				v.Cause = x
			default:
				return nil, r.refuse("unknown_field")
			}
			r.ws()
			if r.at() != ',' {
				break
			}
			r.pos++
		}
	}
	if r.at() != '}' {
		return nil, r.refuse("malformed")
	}
	r.pos++
	r.depth--
	if seen&1 != 1 {
		return nil, r.refuse("missing_field")
	}
	return v, nil
}

func Decode(in []byte) (*Failure, error) {
	r := &reader{buf: in}
	r.ws()
	v, err := r.decodeFailure()
	if err != nil {
		return nil, err
	}
	r.ws()
	if r.pos < len(r.buf) {
		return nil, r.refuse("trailing_bytes")
	}
	return v, nil
}

// ToJSON writes one record of this package, given as a value or a pointer,
// as JSON laid out as its documents are and without the document terminator.
// Anything else, a nil pointer included, is refused with wrong_type.
func ToJSON(v any) (out []byte, err error) {
	defer func() {
		if p := recover(); p != nil {
			if e, ok := p.(*Refusal); ok {
				out, err = nil, e
				return
			}
			panic(p)
		}
	}()
	switch v := v.(type) {
	case Failure:
		return encFailure(nil, &v, 0), nil
	case *Failure:
		if v == nil {
			return nil, &Refusal{Word: "wrong_type"}
		}
		return encFailure(nil, v, 0), nil
	}
	return nil, &Refusal{Word: "wrong_type"}
}

// FromJSON reads one record from data into v, a pointer to a record of this
// package. A refused input returns *Refusal.
func FromJSON(data []byte, v any) error {
	r := &reader{buf: data}
	r.ws()
	switch p := v.(type) {
	case *Failure:
		if p == nil {
			return &Refusal{Word: "wrong_type"}
		}
		x, err := r.decodeFailure()
		if err != nil {
			return err
		}
		r.ws()
		if r.pos < len(r.buf) {
			return r.refuse("trailing_bytes")
		}
		*p = *x
		return nil
	}
	return &Refusal{Word: "wrong_type"}
}

// refusals is in the order two of them are chosen between.

var refusals = []string{"malformed", "bad_string", "number_spelling", "wrong_type", "depth_exceeded", "duplicate_key", "duplicate_field", "unknown_field", "missing_field", "trailing_bytes"}

func refusalRank(word string) int {
	for i, w := range refusals {
		if w == word {
			return i
		}
	}
	return -1
}
